/**
 * Skill logos, drawn as inline SVG so the page downloads nothing extra and no
 * package is needed. Add a new technology by adding a row to SKILL_ICONS: the
 * key is the skill label in lower case, the colour is the brand colour.
 *
 * Sources (path data copied unchanged):
 * - Simple Icons, CC0 1.0 (https://simpleicons.org) for most logos.
 * - Font Awesome Free brands, CC BY 4.0 (https://fontawesome.com/license/free) for AWS.
 * - Material Design Icons, Apache 2.0 for the generic fallback glyphs, used where
 *   no logo is available (DynamoDB, Amazon RDS, CI/CD) and for unknown skills.
 * Logos are trademarks of their owners and are shown only to name the technology.
 */

export interface SkillIcon {
  viewBox: string;
  path: string;
  /** Brand colour. Missing means a generic glyph in a neutral colour. */
  color?: string;
}

