export const FALLBACK_ICON: SkillIcon = { ...SHAPES.p30 };

/** Strips a trailing "(learning)" and lower-cases, so labels match the table. */
export function iconFor(label: string): SkillIcon {
  const key = label.replace(/\s*\(learning\)\s*$/i, "").trim().toLowerCase();
  return SKILL_ICONS[key] ?? FALLBACK_ICON;
}

function luminance(hex: string): number {
  const channel = (offset: number) => {
    const value = parseInt(hex.slice(offset, offset + 2), 16) / 255;
    return value <= 0.03928 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(1) + 0.7152 * channel(3) + 0.0722 * channel(5);
}

/**
 * The colour the logo is drawn in on the dark theme. Brand colours are kept,
 * except the ones that are near-black (GitHub, Next.js, JSON): those would be
 * invisible on this background, so they are drawn light instead.
 */
export function displayColor(icon: SkillIcon): string {
  if (!icon.color) return "#a1a1aa";
  return luminance(icon.color) < 0.12 ? "#e4e4e7" : icon.color;
}
